<?php
session_start(); require_once('check-login.php'); require_once('smartmark-utils.php'); smartmark_ensure_tables($con);
if(!(isset($_SESSION['ACCESSLEVEL'],$_SESSION['SYSTEMTYPE']) && $_SESSION['ACCESSLEVEL']==='user' && $_SESSION['SYSTEMTYPE']==='Teacher')){header('location:index.php');exit();}
$teacherId=(string)$_SESSION['USERID']; $teacherEsc=mysqli_real_escape_string($con,$teacherId); $assignments=smartmark_teacher_assignments($con,$teacherId);
if(empty($_SESSION['smartmark_csrf'])){$_SESSION['smartmark_csrf']=bin2hex(random_bytes(24));} $flash=$_SESSION['smartmark_flash']??null; unset($_SESSION['smartmark_flash']);
function smartmark_redirect($id=0){header('location:smartmark.php'.($id?'?assessment='.(int)$id:''));exit();}
if($_SERVER['REQUEST_METHOD']==='POST' && hash_equals($_SESSION['smartmark_csrf'],$_POST['csrf']??'')){
    $action=$_POST['action']??'';
    if($action==='create'){
        $assignmentId=trim((string)($_POST['assignmentid']??''));$title=trim((string)($_POST['title']??''));$questions=(int)($_POST['questioncount']??0);$options=(int)($_POST['optioncount']??4);$marks=(float)($_POST['marksperquestion']??1);$rawKey=$_POST['answerkey']??array();
        $key=array();foreach(range(1,max(0,$questions)) as $n){$answer=strtoupper(trim((string)($rawKey[$n]??'')));$key[$n]=$answer;}
        if(!isset($assignments[$assignmentId])||$title===''||strlen($title)>160||$questions<1||$questions>100||$options<2||$options>5||$marks<=0||in_array('',array_values($key),true)||array_diff(array_values($key),smartmark_options($options))){$_SESSION['smartmark_flash']=array('error','Complete the assessment details and choose one valid answer for every question.');smartmark_redirect();}
        $a=$assignments[$assignmentId];$stmt=mysqli_prepare($con,'INSERT INTO tblsmartmarkassessment(teacherid,assignmentid,classid,classificationid,batchid,termname,title,questioncount,optioncount,marksperquestion,answerkey) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$json=json_encode($key);mysqli_stmt_bind_param($stmt,'sssssisiids',$teacherId,$a['assignmentid'],$a['classid'],$a['classificationid'],$a['batchid'],$a['termname'],$title,$questions,$options,$marks,$json);$ok=@mysqli_stmt_execute($stmt);$id=mysqli_insert_id($con);mysqli_stmt_close($stmt);$_SESSION['smartmark_flash']=$ok?array('success','Assessment created. Record each student sheet and approve any answer that needs review.'):array('error','The assessment could not be created.');smartmark_redirect($ok?$id:0);
    }
    if($action==='mark'){
        $assessmentId=(int)($_POST['assessmentid']??0);$studentId=trim((string)($_POST['studentid']??''));$res=@mysqli_query($con,"SELECT * FROM tblsmartmarkassessment WHERE assessmentid=$assessmentId AND teacherid='$teacherEsc' AND status='active' LIMIT 1");$assessment=$res?mysqli_fetch_array($res,MYSQLI_ASSOC):null;
        if(!$assessment||$studentId===''){$_SESSION['smartmark_flash']=array('error','Choose a student and an active assessment.');smartmark_redirect($assessmentId);}else{$students=smartmark_students_for_assessment($con,$assessment);$allowed=array_column($students,'userid');if(!in_array($studentId,$allowed,true)){$_SESSION['smartmark_flash']=array('error','That student is not in this assessment class.');smartmark_redirect($assessmentId);}$key=smartmark_decode_key($assessment['answerkey'],$assessment['questioncount'],$assessment['optioncount']);list($answers,$summary)=smartmark_grade_answers($key,$assessment['optioncount'],$assessment['marksperquestion'],$_POST['answers']??array(),$_POST['confidence']??array());$total=(float)$assessment['questioncount']*(float)$assessment['marksperquestion'];$percent=$total>0?round(($summary['score']/$total)*100,2):0;$status=$summary['review']?'review':'approved';$json=json_encode($answers);$stmt=mysqli_prepare($con,"INSERT INTO tblsmartmarkattempt(assessmentid,studentid,answers,correctcount,incorrectcount,blankcount,multiplecount,reviewcount,score,totalscore,percentage,status,markedby) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE answers=VALUES(answers),correctcount=VALUES(correctcount),incorrectcount=VALUES(incorrectcount),blankcount=VALUES(blankcount),multiplecount=VALUES(multiplecount),reviewcount=VALUES(reviewcount),score=VALUES(score),totalscore=VALUES(totalscore),percentage=VALUES(percentage),status=VALUES(status),markedby=VALUES(markedby)");mysqli_stmt_bind_param($stmt,'issiiiiidddss',$assessmentId,$studentId,$json,$summary['correct'],$summary['incorrect'],$summary['blank'],$summary['multiple'],$summary['review'],$summary['score'],$total,$percent,$status,$teacherId);$ok=@mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$_SESSION['smartmark_flash']=$ok?array('success','Result saved: '.number_format($summary['score'],2).'/'.number_format($total,2).($summary['review']?' — review required for '.$summary['review'].' answer(s).':'.')):array('error','The result could not be saved.');smartmark_redirect($assessmentId);}
    }
}
$assessmentId=(int)($_GET['assessment']??0);$assessment=null;if($assessmentId){$res=@mysqli_query($con,"SELECT a.*,ce.class_name,sub.subject FROM tblsmartmarkassessment a LEFT JOIN tblclassentry ce ON ce.class_entryid=a.classid LEFT JOIN tblsubjectclassification sc ON sc.classificationid=a.classificationid LEFT JOIN tblsubject sub ON sub.subjectid=sc.subjectid WHERE a.assessmentid=$assessmentId AND a.teacherid='$teacherEsc' LIMIT 1");$assessment=$res?mysqli_fetch_array($res,MYSQLI_ASSOC):null;}
$recent=array();$res=@mysqli_query($con,"SELECT a.*,ce.class_name,sub.subject,COUNT(t.attemptid) attempts,SUM(t.status='review') reviews FROM tblsmartmarkassessment a LEFT JOIN tblclassentry ce ON ce.class_entryid=a.classid LEFT JOIN tblsubjectclassification sc ON sc.classificationid=a.classificationid LEFT JOIN tblsubject sub ON sub.subjectid=sc.subjectid LEFT JOIN tblsmartmarkattempt t ON t.assessmentid=a.assessmentid WHERE a.teacherid='$teacherEsc' AND a.status='active' GROUP BY a.assessmentid ORDER BY a.createdat DESC LIMIT 12");if($res){while($row=mysqli_fetch_array($res,MYSQLI_ASSOC)){$recent[]=$row;}}
$students=$assessment?smartmark_students_for_assessment($con,$assessment):array();$key=$assessment?smartmark_decode_key($assessment['answerkey'],$assessment['questioncount'],$assessment['optioncount']):array();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartMark</title><?php include('links.php'); ?><link rel="stylesheet" href="css/smartmark.css"></head><body class="smartmark-page"><main class="smartmark-shell"><a class="smartmark-back" href="teacher-page.php"><i class="fa fa-arrow-left"></i> Teacher dashboard</a><section class="smartmark-hero"><div><span>Teacher-supervised marking</span><h1>SmartMark</h1><p>Mark objective tests consistently, keep uncertain responses visible, and retain an auditable class record.</p></div><i class="fa fa-check-square-o"></i></section><?php if($flash){?><div class="smartmark-flash smartmark-flash--<?php echo smartmark_escape($flash[0]);?>"><?php echo smartmark_escape($flash[1]);?></div><?php }?>
<?php if(!$assessment){?><section class="smartmark-card"><div class="smartmark-heading"><div><span>New assessment</span><h2>Set the answer key first</h2></div><p>For standard answer sheets; image scanning can be connected later without changing the marking record.</p></div><?php if($assignments){?><form method="post" class="smartmark-create"><input type="hidden" name="csrf" value="<?php echo smartmark_escape($_SESSION['smartmark_csrf']);?>"><input type="hidden" name="action" value="create"><label>Class and subject<select name="assignmentid" required><option value="">Choose an assigned subject</option><?php foreach($assignments as $a){?><option value="<?php echo smartmark_escape($a['assignmentid']);?>"><?php echo smartmark_escape($a['class_name'].' · '.$a['subject'].' · '.$a['batch'].' · Semester '.$a['termname']);?></option><?php }?></select></label><label>Assessment title<input name="title" maxlength="160" required placeholder="e.g. Week 4 Mathematics quiz"></label><label>Questions<input id="sm-questions" name="questioncount" type="number" value="10" min="1" max="100" required></label><label>Options per question<select id="sm-options" name="optioncount"><option value="4">A–D</option><option value="5">A–E</option></select></label><label>Marks per question<input name="marksperquestion" type="number" value="1" min="0.01" step="0.01" required></label><div class="smartmark-key" id="sm-key"></div><button type="submit" class="smartmark-primary"><i class="fa fa-check"></i> Create assessment</button></form><?php }else{?><p class="smartmark-empty">You need an active subject assignment before creating an assessment.</p><?php }?></section><?php }else{?><section class="smartmark-card"><div class="smartmark-heading"><div><span><?php echo smartmark_escape($assessment['subject'].' · '.$assessment['class_name']);?></span><h2><?php echo smartmark_escape($assessment['title']);?></h2></div><a class="smartmark-secondary" href="smartmark-export.php?assessment=<?php echo (int)$assessment['assessmentid'];?>"><i class="fa fa-download"></i> Export CSV</a></div><p class="smartmark-meta"><?php echo (int)$assessment['questioncount'];?> questions · <?php echo number_format((float)$assessment['marksperquestion'],2);?> marks each · <?php echo implode(', ',array_values($key));?></p><?php if($students){?><form method="post" class="smartmark-mark"><input type="hidden" name="csrf" value="<?php echo smartmark_escape($_SESSION['smartmark_csrf']);?>"><input type="hidden" name="action" value="mark"><input type="hidden" name="assessmentid" value="<?php echo (int)$assessment['assessmentid'];?>"><label class="smartmark-student">Student<select name="studentid" required><option value="">Choose student</option><?php foreach($students as $student){?><option value="<?php echo smartmark_escape($student['userid']);?>"><?php echo smartmark_escape(trim($student['student_name'])?:$student['userid']);?></option><?php }?></select></label><div class="smartmark-answer-grid"><?php foreach($key as $n=>$correct){?><fieldset><legend>Q<?php echo $n;?> <small>Key: <?php echo $correct;?></small></legend><div class="smartmark-answer-options"><?php foreach(smartmark_options($assessment['optioncount']) as $option){?><label><input type="checkbox" name="answers[<?php echo $n;?>][]" value="<?php echo $option;?>"> <?php echo $option;?></label><?php }?></div><label class="smartmark-confidence">Confidence <input name="confidence[<?php echo $n;?>]" type="number" min="0" max="100" value="100">%</label></fieldset><?php }?></div><p class="smartmark-note"><i class="fa fa-eye"></i> Any response below 80% confidence, or with multiple choices, is saved for teacher review.</p><button class="smartmark-primary" type="submit"><i class="fa fa-save"></i> Mark and save result</button></form><?php }else{?><p class="smartmark-empty">No students are registered in this subject/class scope yet.</p><?php }?></section><?php }?>
<section class="smartmark-card"><div class="smartmark-heading"><div><span>Assessment record</span><h2>Recent SmartMark assessments</h2></div></div><?php if($recent){?><div class="smartmark-list"><?php foreach($recent as $item){?><a href="smartmark.php?assessment=<?php echo (int)$item['assessmentid'];?>"><strong><?php echo smartmark_escape($item['title']);?></strong><span><?php echo smartmark_escape($item['subject'].' · '.$item['class_name']);?></span><small><?php echo (int)$item['attempts'];?> marked · <?php echo (int)$item['reviews'];?> need review</small></a><?php }?></div><?php }else{?><p class="smartmark-empty">No assessments yet. Create an answer key to begin.</p><?php }?></section></main><script>(function(){var q=document.getElementById('sm-questions'),o=document.getElementById('sm-options'),key=document.getElementById('sm-key');if(!q||!o||!key)return;function render(){var n=Math.max(1,Math.min(100,parseInt(q.value||10,10))),opts=['A','B','C','D','E'].slice(0,parseInt(o.value,10)),html='<h3>Answer key</h3><p>Select the correct response for each question.</p><div>';for(var i=1;i<=n;i++){html+='<label>Q'+i+'<select required name="answerkey['+i+']"><option value="">–</option>';opts.forEach(function(x){html+='<option>'+x+'</option>';});html+='</select></label>';}key.innerHTML=html+'</div>';}q.addEventListener('input',render);o.addEventListener('change',render);render();}());</script></body></html>
